INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 39, 'Contra Celsum, Book VIII, Chapter 74 (circa 248 AD)', 'For in secret, and in our own hearts, there are prayers which ascend as from priests in behalf of our fellow citizens. And Christians are benefactors of their country more than others.', 'prayer,community,service,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 39 AND text = 'For in secret, and in our own hearts, there are prayers which ascend as from priests in behalf of our fellow citizens. And Christians are benefactors of their country more than others.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 39, 'Contra Celsum, Book VIII, Chapter 72 (circa 248 AD)', 'But our belief is, that the Word shall prevail over the entire rational creation, and change every soul into His own perfection…', 'hope,transformation,sovereignty,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 39 AND text = 'But our belief is, that the Word shall prevail over the entire rational creation, and change every soul into His own perfection…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 39, 'Commentary on Matthew, Book XIV, Chapter 7 (circa 246 AD)', 'For He is the King of the heavens, and as He is absolute Wisdom and absolute Righteousness and absolute Truth, is He not so also absolute Kingdom?', 'sovereignty,truth,wisdom,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 39 AND text = 'For He is the King of the heavens, and as He is absolute Wisdom and absolute Righteousness and absolute Truth, is He not so also absolute Kingdom?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 39, 'On First Principles, Book II, Chapter 11 (circa 220 AD)', '…as the eye naturally seeks the light and vision, and our body naturally desires food and drink, so our mind is possessed with a becoming and natural desire to become acquainted with the truth of God and the causes of things.', 'truth,wisdom,creation,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 39 AND text = '…as the eye naturally seeks the light and vision, and our body naturally desires food and drink, so our mind is possessed with a becoming and natural desire to become acquainted with the truth of God and the causes of things.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 39, 'Contra Celsum, Book III, Chapter 68 (circa 248 AD)', 'And therefore their word ran swiftly and speedily, or rather the word of God through their instrumentality, transformed numbers of persons who had been sinners both by nature and habit, whom no one could have reformed by punishment, but who were changed by the word, which moulded and transformed them according to its pleasure.', 'transformation,word_of_god,grace,redemption', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 39 AND text = 'And therefore their word ran swiftly and speedily, or rather the word of God through their instrumentality, transformed numbers of persons who had been sinners both by nature and habit, whom no one could have reformed by punishment, but who were changed by the word, which moulded and transformed them according to its pleasure.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 39, 'Contra Celsum, Book III, Chapter 69 (circa 248 AD)', 'For deliberate choice and practice avail much towards the accomplishment of things which appear to be very difficult, and, to speak hyperbolically, almost impossible.', 'perseverance,discipline,courage,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 39 AND text = 'For deliberate choice and practice avail much towards the accomplishment of things which appear to be very difficult, and, to speak hyperbolically, almost impossible.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 39, 'Contra Celsum, Book VIII, Chapter 73 (circa 248 AD)', 'And we do take our part in public affairs, when along with righteous prayers we join self-denying exercises and meditations, which teach us to despise pleasures, and not to be led away by them.', 'prayer,service,discipline,justice', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 39 AND text = 'And we do take our part in public affairs, when along with righteous prayers we join self-denying exercises and meditations, which teach us to despise pleasures, and not to be led away by them.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 39, 'Contra Celsum, Book I, Chapter 46 (circa 248 AD)', '…many have been converted to Christianity as if against their will, some sort of spirit having suddenly transformed their minds from a hatred of the doctrine to a readiness to die in its defense…', 'courage,transformation,faith,holy_spirit', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 39 AND text = '…many have been converted to Christianity as if against their will, some sort of spirit having suddenly transformed their minds from a hatred of the doctrine to a readiness to die in its defense…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 39, 'Commentary on John, Book I, Chapter 11 (circa 230 AD)', 'One good thing is life; but Jesus is the life. Another good thing is the light of the world, when it is true light, and the light of men; and all these things the Son of God is said to be.', 'hope,joy,salvation,gospel', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 39 AND text = 'One good thing is life; but Jesus is the life. Another good thing is the light of the world, when it is true light, and the light of men; and all these things the Son of God is said to be.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 39, 'Commentary on John, Book I, Chapter 10 (circa 230 AD)', 'Now what the Gospels say is to be regarded in the light of promises of good things; and we must say that the good things the Apostles announce in this Gospel are simply Jesus.', 'gospel,hope,scripture,joy', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 39 AND text = 'Now what the Gospels say is to be regarded in the light of promises of good things; and we must say that the good things the Apostles announce in this Gospel are simply Jesus.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 39, 'Contra Celsum, Book V, Chapter 33 (circa 248 AD)', 'For we no longer take up sword against nation, nor do we learn war any more, having become children of peace…', 'peace,justice,discipleship,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 39 AND text = 'For we no longer take up sword against nation, nor do we learn war any more, having become children of peace…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 43, 'Exhortation to the Greeks, Chapter 10 (circa 195 AD)', 'Practise husbandry, we say, if you are a husbandman; but while you till your fields, know God. Sail the sea, you who are devoted to navigation, yet call the while on the heavenly Pilot.', 'work,prayer,faith,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 43 AND text = 'Practise husbandry, we say, if you are a husbandman; but while you till your fields, know God. Sail the sea, you who are devoted to navigation, yet call the while on the heavenly Pilot.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 43, 'Exhortation to the Greeks, Chapter 11 (circa 195 AD)', 'He has changed sunset into sunrise, and through the cross brought death to life; and having wrenched man from destruction, He has raised him to the skies…', 'hope,resurrection,salvation,joy', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 43 AND text = 'He has changed sunset into sunrise, and through the cross brought death to life; and having wrenched man from destruction, He has raised him to the skies…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 43, 'The Instructor (Paedagogus), Book III, Chapter 6 (circa 197 AD)', '…it is not he who has and keeps, but he who gives away, that is rich; and it is giving away, not possession, which renders a man happy…', 'generosity,joy,service,justice', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 43 AND text = '…it is not he who has and keeps, but he who gives away, that is rich; and it is giving away, not possession, which renders a man happy…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 43, 'Who Is the Rich Man That Shall Be Saved? Chapter 13 (circa 200 AD)', 'How could one give food to the hungry, and drink to the thirsty, clothe the naked, and shelter the houseless, for not doing which He threatens with fire and the outer darkness, if each man first divested himself of all these things?', 'justice,compassion,service,generosity', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 43 AND text = 'How could one give food to the hungry, and drink to the thirsty, clothe the naked, and shelter the houseless, for not doing which He threatens with fire and the outer darkness, if each man first divested himself of all these things?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 43, 'Stromateis, Book IV, Chapter 4 (circa 198 AD)', 'We call martyrdom perfection, not because the man comes to the end of his life as others, but because he has exhibited the perfect work of love.', 'courage,love,suffering,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 43 AND text = 'We call martyrdom perfection, not because the man comes to the end of his life as others, but because he has exhibited the perfect work of love.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 43, 'Stromateis, Book VII, Chapter 7 (circa 198 AD)', 'Though whispering, consequently, and not opening the lips, we speak in silence, yet we cry inwardly. For God hears continually all the inward converse.', 'prayer,presence,peace,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 43 AND text = 'Though whispering, consequently, and not opening the lips, we speak in silence, yet we cry inwardly. For God hears continually all the inward converse.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 43, 'Stromateis, Book VII, Chapter 12 (circa 198 AD)', 'And we shall take everything for good; even though the exercises that meet us, which Your arrangement brings to us for the discipline of our steadfastness, appear to be evil.', 'providence,suffering,perseverance,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 43 AND text = 'And we shall take everything for good; even though the exercises that meet us, which Your arrangement brings to us for the discipline of our steadfastness, appear to be evil.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 43, 'Who Is the Rich Man That Shall Be Saved? Chapter 27 (circa 200 AD)', '…gaining immortality by the very exercise of loving the Father to the extent of one''s might and power. For the more one loves God, the more he enters within God.', 'love,devotion,worship,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 43 AND text = '…gaining immortality by the very exercise of loving the Father to the extent of one''s might and power. For the more one loves God, the more he enters within God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 45, 'On the Holy Spirit, Chapter 9 (375 AD)', 'Through His aid hearts are lifted up, the weak are held by the hand, and they who are advancing are brought to perfection.', 'holy_spirit,hope,grace,strength', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 45 AND text = 'Through His aid hearts are lifted up, the weak are held by the hand, and they who are advancing are brought to perfection.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 45, 'Letters, Letter 2 (circa 358 AD)', 'What state can be more blessed than to imitate on earth the choruses of angels? To begin the day with prayer, and honour our Maker with hymns and songs? As the day brightens, to betake ourselves, with prayer attending on it throughout, to our labours, and to sweeten our work with hymns, as if with salt?', 'prayer,work,worship,joy', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 45 AND text = 'What state can be more blessed than to imitate on earth the choruses of angels? To begin the day with prayer, and honour our Maker with hymns and songs? As the day brightens, to betake ourselves, with prayer attending on it throughout, to our labours, and to sweeten our work with hymns, as if with salt?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 45, 'Letters, Letter 2 (circa 358 AD)', 'Quiet, then, as I have said, is the first step in our sanctification; the tongue purified from the gossip of the world…', 'peace,holiness,discipline,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 45 AND text = 'Quiet, then, as I have said, is the first step in our sanctification; the tongue purified from the gossip of the world…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 45, 'Letters, Letter 5 (circa 358 AD)', 'Play the man, then, I implore you; the blow is a heavy one, but stand firm; do not fall under the weight of your grief; do not lose heart. Be perfectly assured of this, that though the reasons for what is ordained by God are beyond us, yet always what is arranged for us by Him Who is wise and Who loves us is to be accepted, be it ever so grievous to endure.', 'suffering,courage,providence,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 45 AND text = 'Play the man, then, I implore you; the blow is a heavy one, but stand firm; do not fall under the weight of your grief; do not lose heart. Be perfectly assured of this, that though the reasons for what is ordained by God are beyond us, yet always what is arranged for us by Him Who is wise and Who loves us is to be accepted, be it ever so grievous to endure.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 45, 'Letters, Letter 6 (circa 358 AD)', 'Do not measure your loss by itself; if you do it will seem intolerable; but if you take all human affairs into account you will find that some comfort is to be derived from them.', 'suffering,comfort,wisdom,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 45 AND text = 'Do not measure your loss by itself; if you do it will seem intolerable; but if you take all human affairs into account you will find that some comfort is to be derived from them.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 45, 'Letters, Letter 101 (circa 372 AD)', 'Just as athletes win crowns by their struggles in the arena, so are Christians brought to perfection by the trial of their temptations, if only we learn to accept what is sent us by the Lord with becoming patience, with all thanksgiving.', 'perseverance,suffering,gratitude,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 45 AND text = 'Just as athletes win crowns by their struggles in the arena, so are Christians brought to perfection by the trial of their temptations, if only we learn to accept what is sent us by the Lord with becoming patience, with all thanksgiving.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 45, 'Letters, Letter 174 (circa 374 AD)', 'Anxiety is a good thing; but, on the other hand, despondency, dejection, and despair of our salvation, are injurious to the soul. Trust therefore in the goodness of God, and look for His succour…', 'trust,hope,grace,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 45 AND text = 'Anxiety is a good thing; but, on the other hand, despondency, dejection, and despair of our salvation, are injurious to the soul. Trust therefore in the goodness of God, and look for His succour…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 45, 'Letters, Letter 174 (circa 374 AD)', 'Even while we are living this life in the flesh, prayer will be a mighty helper to us, and when we are departing hence it will be a sufficient provision for us on the journey to the world to come.', 'prayer,hope,perseverance,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 45 AND text = 'Even while we are living this life in the flesh, prayer will be a mighty helper to us, and when we are departing hence it will be a sufficient provision for us on the journey to the world to come.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 45, 'Letters, Letter 206 (circa 375 AD)', 'To the end, then, that you may yourself leave to them that come after you an example of fortitude and of genuine trust in what we hope for, show that you are not vanquished by your grief, but are rising above your sorrows, patient in affliction, and rejoicing in hope.', 'hope,perseverance,suffering,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 45 AND text = 'To the end, then, that you may yourself leave to them that come after you an example of fortitude and of genuine trust in what we hope for, show that you are not vanquished by your grief, but are rising above your sorrows, patient in affliction, and rejoicing in hope.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 45, 'Letters, Letter 243 (circa 376 AD)', 'Wherefore, although we dwell far away from one another, yet, as regards our close conjunction, we are very near.', 'community,unity,love,church', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 45 AND text = 'Wherefore, although we dwell far away from one another, yet, as regards our close conjunction, we are very near.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 45, 'Homilies on the Hexameron, Homily 7 (circa 378 AD)', 'God has foreseen all, He has neglected nothing. His eye, which never sleeps, watches over all. He is present everywhere and gives to each being the means of preservation. If God has not left the sea urchin outside His providence, is He without care for you?', 'providence,creation,trust,presence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 45 AND text = 'God has foreseen all, He has neglected nothing. His eye, which never sleeps, watches over all. He is present everywhere and gives to each being the means of preservation. If God has not left the sea urchin outside His providence, is He without care for you?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 45, 'Homilies on the Hexameron, Homily 1 (circa 378 AD)', 'You will finally discover that the world was not conceived by chance and without reason, but for an useful end and for the great advantage of all beings, since it is really the school where reasonable souls exercise themselves, the training ground where they learn to know God…', 'creation,wisdom,providence,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 45 AND text = 'You will finally discover that the world was not conceived by chance and without reason, but for an useful end and for the great advantage of all beings, since it is really the school where reasonable souls exercise themselves, the training ground where they learn to know God…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 33, 'Cited in Lina Eckenstein, Woman under Monasticism, Chapter VIII (1896)', 'And it happened in the year 1141 of Christ’s incarnation, when I was forty-two years and seven months old, that a fiery light of great brilliancy streaming down from heaven entirely flooded my brain, my heart and my breast, like a flame that flickers not but gives glowing warmth, as the sun warms that on which he sheds his rays.', 'calling,wisdom,scripture,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 33 AND text = 'And it happened in the year 1141 of Christ’s incarnation, when I was forty-two years and seven months old, that a fiery light of great brilliancy streaming down from heaven entirely flooded my brain, my heart and my breast, like a flame that flickers not but gives glowing warmth, as the sun warms that on which he sheds his rays.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 33, 'Cited in Lina Eckenstein, Woman under Monasticism, Chapter VIII (1896)', 'The poor man is very foolish who, when he knows that his garment is soiled, looks at others and reflects on the appearance of their clothes, instead of washing and cleaning his own.', 'humility,integrity,repentance,justice', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 33 AND text = 'The poor man is very foolish who, when he knows that his garment is soiled, looks at others and reflects on the appearance of their clothes, instead of washing and cleaning his own.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 33, 'Cited in Lina Eckenstein, Woman under Monasticism, Chapter VIII (1896)', 'But some of them, although touched by the flames, fell not, others barely kept their footing, yet others falling again to earth, gathered themselves up and went forth anew.', 'perseverance,courage,hope,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 33 AND text = 'But some of them, although touched by the flames, fell not, others barely kept their footing, yet others falling again to earth, gathered themselves up and went forth anew.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 33, 'Cited in Lina Eckenstein, Woman under Monasticism, Chapter VIII (1896)', 'God, who disposes all in wisdom, summons His faithful band to the glory of their heritage; the old deceiver lies in wait and tries his evil powers, but he is overcome, his presumption is defeated; they attain their heavenly heritage, and he suffers eternal disgrace.', 'hope,providence,courage,victory', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 33 AND text = 'God, who disposes all in wisdom, summons His faithful band to the glory of their heritage; the old deceiver lies in wait and tries his evil powers, but he is overcome, his presumption is defeated; they attain their heavenly heritage, and he suffers eternal disgrace.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 33, 'Cited in Charles Singer, Studies in the History and Method of Science, Vol. I (1917)', 'God, who created all things, wrought also man in his own image and similitude, and in him he traced … all created things, and he held him in such love that he destined him for the place from which the fallen angel had been cast.', 'creation,love,grace,humanity', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 33 AND text = 'God, who created all things, wrought also man in his own image and similitude, and in him he traced … all created things, and he held him in such love that he destined him for the place from which the fallen angel had been cast.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 33, 'Cited in Charles Singer, Studies in the History and Method of Science, Vol. I (1917)', 'But the affliction laid upon me did not fully cease; yet was my spirit daily strengthened.', 'perseverance,suffering,strength,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 33 AND text = 'But the affliction laid upon me did not fully cease; yet was my spirit daily strengthened.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 33, 'Cited in Charles Singer, Studies in the History and Method of Science, Vol. I (1917)', 'The soul vivifies the body and inspires the senses; the body attracts the soul and reveals the senses; the senses affect the soul and allure the body. For the soul rules the body as a flame throws light into darkness…', 'wisdom,creation,holiness,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 33 AND text = 'The soul vivifies the body and inspires the senses; the body attracts the soul and reveals the senses; the senses affect the soul and allure the body. For the soul rules the body as a flame throws light into darkness…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 33, 'Cited in Henry Osborn Taylor, The Mediaeval Mind, Vol. I, Chapter XX (1911)', 'O King, it is very needful that thou be foreseeing in thy affairs.…See also to it that thou art such that the grace of God may not be lacking in thee.', 'leadership,justice,grace,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 33 AND text = 'O King, it is very needful that thou be foreseeing in thy affairs.…See also to it that thou art such that the grace of God may not be lacking in thee.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 33, 'Cited in Henry Osborn Taylor, The Mediaeval Mind, Vol. I, Chapter XX (1911)', 'And I am perpetually bound by my infirmities and with pains so severe as to threaten death, but hitherto God has raised me up.', 'suffering,perseverance,providence,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 33 AND text = 'And I am perpetually bound by my infirmities and with pains so severe as to threaten death, but hitherto God has raised me up.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 33, 'Cited in Henry Osborn Taylor, The Mediaeval Mind, Vol. I, Chapter XX (1911)', 'When and how I see it I cannot tell; but sometimes when I see it, all sadness and pain is lifted from me, and then I have the ways of a simple girl and not those of an old woman.', 'joy,hope,suffering,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 33 AND text = 'When and how I see it I cannot tell; but sometimes when I see it, all sadness and pain is lifted from me, and then I have the ways of a simple girl and not those of an old woman.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 33, 'Cited in Henry Osborn Taylor, The Mediaeval Mind, Vol. I, Chapter XX (1911)', 'This speculative knowledge shines in the brightness of the light of day, that through it men may see and consider their acts.', 'truth,wisdom,discernment,integrity', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 33 AND text = 'This speculative knowledge shines in the brightness of the light of day, that through it men may see and consider their acts.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 33, 'Cited in Henry Osborn Taylor, The Mediaeval Mind, Vol. I, Chapter XX (1911)', 'Then I saw a most glorious light and in it a human form of sapphire hue, all aflame with a most gentle glowing fire; and that glorious light was infused in the glowing fire, and the fire was infused in the glorious light…', 'worship,theology,beauty,holy_spirit', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 33 AND text = 'Then I saw a most glorious light and in it a human form of sapphire hue, all aflame with a most gentle glowing fire; and that glorious light was infused in the glowing fire, and the fire was infused in the glorious light…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 47, 'Theological Orations, Oration 29, Section 20 (circa 380 AD)', 'He was wearied, but He is the Rest of them that are weary and heavy laden.', 'hope,peace,incarnation,rest', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 47 AND text = 'He was wearied, but He is the Rest of them that are weary and heavy laden.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 47, 'Theological Orations, Oration 29, Section 20 (circa 380 AD)', 'He dies, but He gives life, and by His death destroys death. He is buried, but He rises again; He goes down into Hell, but He brings up the souls; He ascends to Heaven, and shall come again to judge the quick and the dead', 'hope,resurrection,salvation,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 47 AND text = 'He dies, but He gives life, and by His death destroys death. He is buried, but He rises again; He goes down into Hell, but He brings up the souls; He ascends to Heaven, and shall come again to judge the quick and the dead');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 47, 'Oration 2: In Defence of His Flight, Section 16 (circa 362 AD)', 'For the guiding of man, the most variable and manifold of creatures, seems to me in very deed to be the art of arts and science of sciences.', 'leadership,service,wisdom,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 47 AND text = 'For the guiding of man, the most variable and manifold of creatures, seems to me in very deed to be the art of arts and science of sciences.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 47, 'Oration 2: In Defence of His Flight, Section 71 (circa 362 AD)', 'A man must himself be cleansed, before cleansing others: himself become wise, that he may make others wise; become light, and then give light: draw near to God, and so bring others near; be hallowed, then hallow them', 'holiness,leadership,integrity,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 47 AND text = 'A man must himself be cleansed, before cleansing others: himself become wise, that he may make others wise; become light, and then give light: draw near to God, and so bring others near; be hallowed, then hallow them');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 47, 'Oration 45: On Holy Easter, Section 28 (circa 383 AD)', 'We needed an Incarnate God, a God put to death, that we might live. We were put to death together with Him, that we might be cleansed; we rose again with Him because we were put to death with Him', 'salvation,resurrection,hope,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 47 AND text = 'We needed an Incarnate God, a God put to death, that we might live. We were put to death together with Him, that we might be cleansed; we rose again with Him because we were put to death with Him');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 47, 'Oration 43: Funeral Oration on Basil the Great, Section 20 (circa 382 AD)', 'We struggled, not each to gain the first place for himself, but to yield it to the other; for we made each other''s reputation to be our own. We seemed to have one soul, inhabiting two bodies.', 'friendship,humility,love,community', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 47 AND text = 'We struggled, not each to gain the first place for himself, but to yield it to the other; for we made each other''s reputation to be our own. We seemed to have one soul, inhabiting two bodies.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 47, 'Oration 43: Funeral Oration on Basil the Great, Section 63 (circa 382 AD)', 'A noble thing is philanthropy, and the support of the poor, and the assistance of human weakness.', 'compassion,service,justice,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 47 AND text = 'A noble thing is philanthropy, and the support of the poor, and the assistance of human weakness.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 47, 'Oration 38: On the Theophany, Section 1 (circa 380 AD)', 'Christ is born, glorify Him. Christ from heaven, go out to meet Him. Christ on earth; be exalted.', 'joy,worship,incarnation,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 47 AND text = 'Christ is born, glorify Him. Christ from heaven, go out to meet Him. Christ on earth; be exalted.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 47, 'Oration 38: On the Theophany, Section 13 (circa 380 AD)', 'And He Who gives riches becomes poor, for He assumes the poverty of my flesh, that I may assume the richness of His Godhead. He that is full empties Himself, for He empties Himself of His glory for a short while, that I may have a share in His Fulness.', 'incarnation,grace,humility,salvation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 47 AND text = 'And He Who gives riches becomes poor, for He assumes the poverty of my flesh, that I may assume the richness of His Godhead. He that is full empties Himself, for He empties Himself of His glory for a short while, that I may have a share in His Fulness.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 47, 'Oration 16: On His Father''s Silence, Section 14 (circa 373 AD)', 'And when He has laid aside that which is unnatural to Him, His anger, He will betake Himself to that which is natural, His mercy. To the one He is forced by us, to the other He is inclined.', 'mercy,hope,repentance,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 47 AND text = 'And when He has laid aside that which is unnatural to Him, His anger, He will betake Himself to that which is natural, His mercy. To the one He is forced by us, to the other He is inclined.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 48, 'On the Duties of the Clergy, Book I, Chapter 11 (circa 391 AD)', 'Mercy, also, is a good thing, for it makes men perfect, in that it imitates the perfect Father. Nothing graces the Christian soul so much as mercy; mercy as shown chiefly towards the poor', 'mercy,compassion,service,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 48 AND text = 'Mercy, also, is a good thing, for it makes men perfect, in that it imitates the perfect Father. Nothing graces the Christian soul so much as mercy; mercy as shown chiefly towards the poor');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 48, 'On the Duties of the Clergy, Book I, Chapter 27 (circa 391 AD)', 'For courage, which in war preserves one''s country from the barbarians, or at home defends the weak, or comrades from robbers, is full of justice', 'courage,justice,service,protection', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 48 AND text = 'For courage, which in war preserves one''s country from the barbarians, or at home defends the weak, or comrades from robbers, is full of justice');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 48, 'On the Duties of the Clergy, Book I, Chapter 28 (circa 391 AD)', 'God has ordered all things to be produced, so that there should be food in common to all, and that the earth should be a common possession for all. Nature, therefore, has produced a common right for all, but greed has made it a right for a few.', 'justice,creation,generosity,stewardship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 48 AND text = 'God has ordered all things to be produced, so that there should be food in common to all, and that the earth should be a common possession for all. Nature, therefore, has produced a common right for all, but greed has made it a right for a few.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 48, 'On the Duties of the Clergy, Book I, Chapter 2 (circa 391 AD)', 'Now what ought we to learn before everything else, but to be silent, that we may be able to speak?', 'wisdom,humility,speech,discipline', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 48 AND text = 'Now what ought we to learn before everything else, but to be silent, that we may be able to speak?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 48, 'On the Duties of the Clergy, Book II, Chapter 4 (circa 391 AD)', 'Nay, he was the more blessed, for he was rich toward God. It is better to be rich for others than for oneself.', 'generosity,service,contentment,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 48 AND text = 'Nay, he was the more blessed, for he was rich toward God. It is better to be rich for others than for oneself.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 48, 'On the Duties of the Clergy, Book II, Chapter 15 (circa 391 AD)', 'The highest kind of liberality is, to redeem captives, to save them from the hands of their enemies, to snatch men from death, and, most of all, women from shame, to restore children to their parents, parents to their children, and, to give back a citizen to his country.', 'justice,compassion,service,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 48 AND text = 'The highest kind of liberality is, to redeem captives, to save them from the hands of their enemies, to snatch men from death, and, most of all, women from shame, to restore children to their parents, parents to their children, and, to give back a citizen to his country.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 48, 'On the Duties of the Clergy, Book II, Chapter 28 (circa 391 AD)', 'The Church has gold, not to store up, but to lay out, and to spend on those who need.', 'generosity,justice,service,stewardship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 48 AND text = 'The Church has gold, not to store up, but to lay out, and to spend on those who need.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 48, 'Letters, Letter 51 to Theodosius (390 AD)', 'You are a man, and it has come upon you, conquer it. Sin is not done away but by tears and penitence.', 'repentance,courage,humility,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 48 AND text = 'You are a man, and it has come upon you, conquer it. Sin is not done away but by tears and penitence.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 48, 'On Penance, Book I, Chapter 1 (circa 390 AD)', 'Now no one can repent to good purpose unless he hopes for mercy.', 'repentance,hope,mercy,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 48 AND text = 'Now no one can repent to good purpose unless he hopes for mercy.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 48, 'On the Death of Satyrus, Book I, Section 70 (378 AD)', 'But from us, for whom death is the end not of our nature but of this life only, since our nature itself is restored to a better state, let the advent of death wipe away all tears.', 'hope,grief,resurrection,comfort', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 48 AND text = 'But from us, for whom death is the end not of our nature but of this life only, since our nature itself is restored to a better state, let the advent of death wipe away all tears.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 48, 'On the Death of Satyrus, Book I, Section 71 (378 AD)', 'for they seem to be not lost but sent before, whom death is not going to swallow up, but eternity to receive.', 'hope,grief,eternity,comfort', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 48 AND text = 'for they seem to be not lost but sent before, whom death is not going to swallow up, but eternity to receive.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 49, 'Letter 60 to Heliodorus, Section 16 (396 AD)', 'Churches have been overthrown, horses have been stalled by the altars of Christ, the relics of martyrs have been dug up.…The Roman world is falling: yet we hold up our heads instead of bowing them.', 'humility,repentance,suffering,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 49 AND text = 'Churches have been overthrown, horses have been stalled by the altars of Christ, the relics of martyrs have been dug up.…The Roman world is falling: yet we hold up our heads instead of bowing them.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 49, 'Letter 60 to Heliodorus, Section 7 (396 AD)', 'Do not grieve that you have lost such a paragon: rejoice rather that he has once been yours.', 'grief,gratitude,comfort,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 49 AND text = 'Do not grieve that you have lost such a paragon: rejoice rather that he has once been yours.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 49, 'Letter 52 to Nepotianus, Section 7 (394 AD)', 'Do not let your deeds belie your words; lest when you speak in church someone may mentally reply Why do you not practise what you profess?', 'integrity,truth,leadership,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 49 AND text = 'Do not let your deeds belie your words; lest when you speak in church someone may mentally reply Why do you not practise what you profess?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 49, 'Letter 52 to Nepotianus, Section 7 (394 AD)', 'Read the divine scriptures constantly; never, indeed, let the sacred volume be out of your hand. Learn what you have to teach.', 'scripture,discipline,wisdom,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 49 AND text = 'Read the divine scriptures constantly; never, indeed, let the sacred volume be out of your hand. Learn what you have to teach.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 49, 'Letter 52 to Nepotianus, Section 9 (394 AD)', 'The rude and simple brother must not suppose himself a saint just because he knows nothing; and he who is educated and eloquent must not measure his saintliness merely by his fluency. Of two imperfect things holy rusticity is better than sinful eloquence.', 'humility,holiness,wisdom,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 49 AND text = 'The rude and simple brother must not suppose himself a saint just because he knows nothing; and he who is educated and eloquent must not measure his saintliness merely by his fluency. Of two imperfect things holy rusticity is better than sinful eloquence.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 49, 'Letter 52 to Nepotianus, Section 10 (394 AD)', 'Many build churches nowadays; their walls and pillars of glowing marble, their ceilings glittering with gold, their altars studded with jewels. Yet to the choice of Christ''s ministers no heed is paid.', 'integrity,leadership,justice,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 49 AND text = 'Many build churches nowadays; their walls and pillars of glowing marble, their ceilings glittering with gold, their altars studded with jewels. Yet to the choice of Christ''s ministers no heed is paid.');
