INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 49, 'Letter 22 to Eustochium, Section 32 (384 AD)', 'Parchments are dyed purple, gold is melted into lettering, manuscripts are decked with jewels, while Christ lies at the door naked and dying.', 'justice,compassion,poverty,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 49 AND text = 'Parchments are dyed purple, gold is melted into lettering, manuscripts are decked with jewels, while Christ lies at the door naked and dying.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 49, 'Letter 108 on the Death of Paula, Section 15 (404 AD)', 'If she saw a poor man, she supported him: and if she saw a rich one, she urged him to do good. Her liberality alone knew no bounds.', 'generosity,compassion,service,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 49 AND text = 'If she saw a poor man, she supported him: and if she saw a rich one, she urged him to do good. Her liberality alone knew no bounds.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 49, 'Life of Malchus, Section 10 (circa 391 AD)', 'Tell the story to them that come after, that they may realize that in the midst of swords, and wild beasts of the desert, virtue is never a captive, and that he who is devoted to the service of Christ may die, but cannot be conquered.', 'courage,perseverance,faith,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 49 AND text = 'Tell the story to them that come after, that they may realize that in the midst of swords, and wild beasts of the desert, virtue is never a captive, and that he who is devoted to the service of Christ may die, but cannot be conquered.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 49, 'Letter 58 to Paulinus, Section 2 (395 AD)', 'What is praiseworthy is not to have been at Jerusalem but to have lived a good life while there.', 'integrity,holiness,discipleship,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 49 AND text = 'What is praiseworthy is not to have been at Jerusalem but to have lived a good life while there.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 35, 'The Fire of Love, Book I, Chapter 19 (circa 1343)', 'Truly in the love of God is the love of my neighbour. Therefore as he that loves God knows not but to love man, so he that truly knows to love Christ is proved to love nothing in himself but God.', 'love,love_of_neighbour,devotion,community', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 35 AND text = 'Truly in the love of God is the love of my neighbour. Therefore as he that loves God knows not but to love man, so he that truly knows to love Christ is proved to love nothing in himself but God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 35, 'The Fire of Love, Book I, Chapter 27 (circa 1343)', 'Therefore marvel not though thou be noyed with divers and many temptations; for if thou withstand steadfastly, thou shalt be dearer and sweeter before God. Have in mind that God proves His own as gold is proved by fire.', 'perseverance,suffering,faith,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 35 AND text = 'Therefore marvel not though thou be noyed with divers and many temptations; for if thou withstand steadfastly, thou shalt be dearer and sweeter before God. Have in mind that God proves His own as gold is proved by fire.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 35, 'The Fire of Love, Book II, Chapter 10 (circa 1343)', 'When this love…is rooted in the heavens, neither prosperity nor adversity may change it, as the wisest men have written. Then no marvel it shall turn the night to day, darkness to light, heaviness to melody, noy to solace, and labour to sweet rest.', 'love,hope,perseverance,joy', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 35 AND text = 'When this love…is rooted in the heavens, neither prosperity nor adversity may change it, as the wisest men have written. Then no marvel it shall turn the night to day, darkness to light, heaviness to melody, noy to solace, and labour to sweet rest.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 35, 'The Fire of Love, Book II, Chapter 10 (circa 1343)', 'And if we be in labour of our hands what lets us to lift our hearts to heaven and without ceasing to hold the thought of endless love?', 'work,prayer,devotion,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 35 AND text = 'And if we be in labour of our hands what lets us to lift our hearts to heaven and without ceasing to hold the thought of endless love?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 35, 'Mending of Life, Chapter 6 (circa 1340)', 'When temptations arise or tribulation, ghostly armour is to be taken and it is time to go to battle. Temptations truly are overcome with steadfastness of faith and love; tribulation truly with patience.', 'perseverance,suffering,faith,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 35 AND text = 'When temptations arise or tribulation, ghostly armour is to be taken and it is time to go to battle. Temptations truly are overcome with steadfastness of faith and love; tribulation truly with patience.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 35, 'Mending of Life, Chapter 6 (circa 1340)', 'it is needful to take the shield of patience and be readier to forget wrongs than to know them. He shall pray for their turning that hate him and cast him down, and shall care not to please man, but dread to offend God.', 'forgiveness,patience,prayer,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 35 AND text = 'it is needful to take the shield of patience and be readier to forget wrongs than to know them. He shall pray for their turning that hate him and cast him down, and shall care not to please man, but dread to offend God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 35, 'Mending of Life, Chapter 7 (circa 1340)', 'Truly then we pray well when we think of no other thing, but all our mind is dressed to heaven and our soul is enflamed with the fire of the Holy Ghost.', 'prayer,devotion,holy_spirit,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 35 AND text = 'Truly then we pray well when we think of no other thing, but all our mind is dressed to heaven and our soul is enflamed with the fire of the Holy Ghost.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 35, 'Mending of Life, Chapter 12 (circa 1340)', 'In reading God speaks to us; in prayer we speak to God.…Prayer certain is a meek desire of the mind dressed in God, with which, when it comes to Him, He is pleased.', 'prayer,scripture,humility,devotion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 35 AND text = 'In reading God speaks to us; in prayer we speak to God.…Prayer certain is a meek desire of the mind dressed in God, with which, when it comes to Him, He is pleased.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 35, 'The Form of Living, Chapter 10 (circa 1348)', 'If thou wilt ask how good is he or she, ask how much he or she loves; and that no man can tell.', 'love,humility,judgment,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 35 AND text = 'If thou wilt ask how good is he or she, ask how much he or she loves; and that no man can tell.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Men, Letter 1', 'It is a peace which makes a man at one with himself, a peace never broken or disturbed save by unfaithfulness. And so the less a man is unfaithful, the more he enjoys this blessed peace. As the world cannot give such, neither can it take this peace away.', 'peace,faithfulness,holiness,joy', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'It is a peace which makes a man at one with himself, a peace never broken or disturbed save by unfaithfulness. And so the less a man is unfaithful, the more he enjoys this blessed peace. As the world cannot give such, neither can it take this peace away.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Men, Letter 39', 'When we learn stedfastly to put aside all restless, unnecessary anxiety, which springs from a love of self very different from true love, we shall have attained the very heart of the narrow way, and, lacking in nothing towards God or man, we shall enjoy the pure liberty and the innocent peace of His children.', 'peace,anxiety,trust,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'When we learn stedfastly to put aside all restless, unnecessary anxiety, which springs from a love of self very different from true love, we shall have attained the very heart of the narrow way, and, lacking in nothing towards God or man, we shall enjoy the pure liberty and the innocent peace of His children.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Men, Letter 41', 'Those who accept what they suffer have no suffering of the will, and thus they are in peace.', 'suffering,peace,surrender,acceptance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'Those who accept what they suffer have no suffering of the will, and thus they are in peace.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Men, Letter 51', 'As to your faults, bear them patiently, as you would bear those of others, without over-indulgence or false excuses.', 'patience,humility,repentance,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'As to your faults, bear them patiently, as you would bear those of others, without over-indulgence or false excuses.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Men, Letter 78', 'Freedom of heart, peace of conscience, the rest of lying still in God''s Hands, the joy of seeing His Light ever brighter and brighter, and the dropping off of worldly fears and hopes, make this hundred-fold happiness which the faithful children of God experience, even amid the heaviest crosses.', 'joy,peace,trust,suffering', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'Freedom of heart, peace of conscience, the rest of lying still in God''s Hands, the joy of seeing His Light ever brighter and brighter, and the dropping off of worldly fears and hopes, make this hundred-fold happiness which the faithful children of God experience, even amid the heaviest crosses.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Men, Letter 80', 'There is but one sin which makes us unworthy of that Mercy, and that is if we harden ourselves against it, and refuse to hope for it.', 'hope,mercy,grace,repentance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'There is but one sin which makes us unworthy of that Mercy, and that is if we harden ourselves against it, and refuse to hope for it.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Men, Letter 81', 'If patience fails you under pressure of pain, appeal to God for support, as you would call to a passer-by for help under an overwhelming burthen. And if you yield to impatience, do not add the further evil of discouragement.', 'patience,suffering,prayer,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'If patience fails you under pressure of pain, appeal to God for support, as you would call to a passer-by for help under an overwhelming burthen. And if you yield to impatience, do not add the further evil of discouragement.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Women, Letter 12', 'True humility lies in seeing one''s own unworthiness, and giving one''s self up to God, never doubting that He can work out the greatest results for and in us.', 'humility,trust,surrender,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'True humility lies in seeing one''s own unworthiness, and giving one''s self up to God, never doubting that He can work out the greatest results for and in us.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Women, Letter 50', 'Even if you have disappointed God hundreds of times, return sincerely to Him, cease to resist Him, and He will at once open His Arms to you.', 'grace,repentance,mercy,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'Even if you have disappointed God hundreds of times, return sincerely to Him, cease to resist Him, and He will at once open His Arms to you.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Women, Letter 72', 'Silence, peace, and union with God ought to comfort you under whatever men may falsely say.', 'peace,truth,comfort,patience', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'Silence, peace, and union with God ought to comfort you under whatever men may falsely say.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Women, Letter 81', 'You will not be free from suffering, but a peaceful suffering is one half relieved.', 'suffering,peace,acceptance,comfort', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'You will not be free from suffering, but a peaceful suffering is one half relieved.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Women, Letter 93', 'Would you like God to be as critical and hard towards you as you often are towards your neighbour?', 'love_of_neighbor,humility,mercy,compassion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'Would you like God to be as critical and hard towards you as you often are towards your neighbour?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'The Spiritual Letters of Fénelon, Letters to Women, Letter 96', 'We can only win the Guiding Spirit by prayer, and time which seems wasted in it is our best spent time.', 'prayer,discipleship,guidance,devotion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'We can only win the Guiding Spirit by prayer, and time which seems wasted in it is our best spent time.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 24, 'Maxims of the Saints, Article 8 (1697)', 'The more cheerfully and faithfully we give ourselves to God, to be smitten in any and all of our idols, whenever and wherever He chooses, the shorter will be the work. God makes us to suffer no longer than He sees to be necessary for us.', 'suffering,surrender,providence,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 24 AND text = 'The more cheerfully and faithfully we give ourselves to God, to be smitten in any and all of our idols, whenever and wherever He chooses, the shorter will be the work. God makes us to suffer no longer than He sees to be necessary for us.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'A Short and Easy Method of Prayer, Chapter 1 (1685)', 'Prayer is the key of perfection and of sovereign happiness; it is the efficacious means of getting rid of all vices and of acquiring all virtues; for the way to become perfect is to live in the presence of God.', 'prayer,holiness,presence_of_god,devotion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'Prayer is the key of perfection and of sovereign happiness; it is the efficacious means of getting rid of all vices and of acquiring all virtues; for the way to become perfect is to live in the presence of God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'A Short and Easy Method of Prayer, Chapter 1 (1685)', 'Nothing can interrupt the prayer of the heart but unruly affections; and when once we have tasted of the love of God, it is impossible to find our delight in anything but Himself. Nothing is easier than to have God and to live upon Him.', 'prayer,love,joy,devotion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'Nothing can interrupt the prayer of the heart but unruly affections; and when once we have tasted of the love of God, it is impossible to find our delight in anything but Himself. Nothing is easier than to have God and to live upon Him.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'A Short and Easy Method of Prayer, Chapter 3 (1685)', 'Go, then, to prayer, not only to enjoy God, but to be as He wills: this will keep you equal in times of barrenness and in times of abundance; and you will not be dismayed by the repulses of God, nor by His apparent indifference.', 'prayer,perseverance,obedience,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'Go, then, to prayer, not only to enjoy God, but to be as He wills: this will keep you equal in times of barrenness and in times of abundance; and you will not be dismayed by the repulses of God, nor by His apparent indifference.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'A Short and Easy Method of Prayer, Chapter 4 (1685)', 'Be patient in prayer, even though you should do nothing all your life but wait in patience, with a heart humbled, abandoned, resigned, and content for the return of your Beloved.', 'patience,prayer,perseverance,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'Be patient in prayer, even though you should do nothing all your life but wait in patience, with a heart humbled, abandoned, resigned, and content for the return of your Beloved.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'A Short and Easy Method of Prayer, Chapter 6 (1685)', 'Be content with all the suffering that God may lay upon you. If you will love Him purely, you will be as willing to follow Him to Calvary as to Tabor.', 'suffering,love,discipleship,surrender', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'Be content with all the suffering that God may lay upon you. If you will love Him purely, you will be as willing to follow Him to Calvary as to Tabor.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'A Short and Easy Method of Prayer, Chapter 9 (1685)', 'When the passions rise, a look towards God, who is present within us, easily deadens them.', 'peace,presence_of_god,prayer,self_control', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'When the passions rise, a look towards God, who is present within us, easily deadens them.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'A Short and Easy Method of Prayer, Chapter 10 (1685)', 'The heart is not a fortified place, which must be taken by cannonading and violence: it is a kingdom of peace, which is possessed by love.', 'peace,love,prayer,gentleness', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'The heart is not a fortified place, which must be taken by cannonading and violence: it is a kingdom of peace, which is possessed by love.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'A Short and Easy Method of Prayer, Chapter 10 (1685)', 'Why do you not throw yourself at once into the arms of Love, who only stretched them out upon the cross in order to take you in? What risk can there be in trusting God, and abandoning yourself to Him?', 'trust,surrender,love,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'Why do you not throw yourself at once into the arms of Love, who only stretched them out upon the cross in order to take you in? What risk can there be in trusting God, and abandoning yourself to Him?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'A Short and Easy Method of Prayer, Chapter 14 (1685)', 'A truly humble soul does not marvel at its weakness, and the more it perceives its wretchedness, the more it abandons itself to God, and seeks to remain near to Him, knowing how deeply it needs His help.', 'humility,trust,grace,surrender', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'A truly humble soul does not marvel at its weakness, and the more it perceives its wretchedness, the more it abandons itself to God, and seeks to remain near to Him, knowing how deeply it needs His help.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'Autobiography of Madame Guyon, Part I, Chapter 5 (1720)', 'Let the poor come, let the ignorant and carnal come; let the children without reason or knowledge come, let the dull or hard hearts which can retain nothing come to the practice of prayer and they shall become wise.', 'prayer,grace,wisdom,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'Let the poor come, let the ignorant and carnal come; let the children without reason or knowledge come, let the dull or hard hearts which can retain nothing come to the practice of prayer and they shall become wise.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'Autobiography of Madame Guyon, Part I, Chapter 11 (1720)', 'O ye poor souls, who exhaust yourselves with needless vexation, if you would but seek God in your hearts, there would be a speedy end to all your troubles.', 'peace,prayer,anxiety,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'O ye poor souls, who exhaust yourselves with needless vexation, if you would but seek God in your hearts, there would be a speedy end to all your troubles.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'Autobiography of Madame Guyon, Part I, Chapter 15 (1720)', 'The peace I enjoyed within, on account of that perfect resignation, in which God kept me by His grace, was so great, that it made me forget myself, in the midst of oppressive disorders.', 'peace,surrender,grace,suffering', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'The peace I enjoyed within, on account of that perfect resignation, in which God kept me by His grace, was so great, that it made me forget myself, in the midst of oppressive disorders.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 25, 'Spiritual Torrents, Part I, Chapter 2 (written circa 1682)', 'Therefore, if one who has never known such religion comes to you to learn it, teach him to love God much, and to let himself go with a perfect abandonment into love, and he will soon know it. If it be a nature slow to love, let him do his best, and wait in patience till love itself make itself beloved in its own way, and not in yours.', 'love,surrender,patience,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 25 AND text = 'Therefore, if one who has never known such religion comes to you to learn it, teach him to love God much, and to let himself go with a perfect abandonment into love, and he will soon know it. If it be a nature slow to love, let him do his best, and wait in patience till love itself make itself beloved in its own way, and not in yours.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 90, 'Cited in August Gottlieb Spangenberg, The Life of Nicholas Lewis, Count Zinzendorf (1838)', 'Our first thought on hearing intelligence, of whatever nature, ought to be, Thanks and praise to God! this will prove another masterpiece of his faithfulness.', 'gratitude,providence,faithfulness,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 90 AND text = 'Our first thought on hearing intelligence, of whatever nature, ought to be, Thanks and praise to God! this will prove another masterpiece of his faithfulness.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 90, 'Cited in August Gottlieb Spangenberg, The Life of Nicholas Lewis, Count Zinzendorf (1838)', 'Every thing that is of importance, either to my mind or my heart, I can commit and confide to my Saviour. That with which I should be ashamed to trouble the meanest brother who serves me, I can cast upon my Redeemer, and pour out my complaint into his ear and his heart.', 'prayer,trust,devotion,comfort', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 90 AND text = 'Every thing that is of importance, either to my mind or my heart, I can commit and confide to my Saviour. That with which I should be ashamed to trouble the meanest brother who serves me, I can cast upon my Redeemer, and pour out my complaint into his ear and his heart.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 90, 'Cited in August Gottlieb Spangenberg, The Life of Nicholas Lewis, Count Zinzendorf (1838)', '…whenever I am placed in a dangerous and critical situation, the first thing I do, is, to examine whether I am myself to blame for it. If I find any thing with which he is not satisfied, I immediately fall at his feet, and ask forgiveness.', 'humility,repentance,courage,prayer', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 90 AND text = '…whenever I am placed in a dangerous and critical situation, the first thing I do, is, to examine whether I am myself to blame for it. If I find any thing with which he is not satisfied, I immediately fall at his feet, and ask forgiveness.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 90, 'Cited in August Gottlieb Spangenberg, The Life of Nicholas Lewis, Count Zinzendorf (1838)', 'People vie with each other in showing me kindness, so that I clearly see, God intends to prove to me here, that I have lost nothing by following in the footsteps of his Son. But I long only the more to return to my blessed sphere of affliction, where I gently reposed under so much that was oppressive.', 'discipleship,suffering,humility,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 90 AND text = 'People vie with each other in showing me kindness, so that I clearly see, God intends to prove to me here, that I have lost nothing by following in the footsteps of his Son. But I long only the more to return to my blessed sphere of affliction, where I gently reposed under so much that was oppressive.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 90, 'Cited in August Gottlieb Spangenberg, The Life of Nicholas Lewis, Count Zinzendorf (1838)', '…the Saviour is as gracious to a small company as to a multitude. He only seeks to possess the whole heart, to which he so gladly approaches and imparts himself.', 'grace,hope,love,community', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 90 AND text = '…the Saviour is as gracious to a small company as to a multitude. He only seeks to possess the whole heart, to which he so gladly approaches and imparts himself.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 90, 'Cited in August Gottlieb Spangenberg, The Life of Nicholas Lewis, Count Zinzendorf (1838)', 'Now, my dear son, I am going to the Saviour, I am ready, I am quite resigned to the will of my Lord, and he is satisfied with me. If he is no longer willing to make use of me here, I am quite ready to go to him…', 'surrender,hope,faith,death', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 90 AND text = 'Now, my dear son, I am going to the Saviour, I am ready, I am quite resigned to the will of my Lord, and he is satisfied with me. If he is no longer willing to make use of me here, I am quite ready to go to him…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 90, 'Cited in August Gottlieb Spangenberg, The Life of Nicholas Lewis, Count Zinzendorf (1838)', 'My daily meditation is, O that I might please my suffering Lord, who became a martyr for me; the faithful friend whom my soul loveth; the God who is my joy and delight!', 'devotion,love,joy,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 90 AND text = 'My daily meditation is, O that I might please my suffering Lord, who became a martyr for me; the faithful friend whom my soul loveth; the God who is my joy and delight!');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 90, 'Cited in August Gottlieb Spangenberg, The Life of Nicholas Lewis, Count Zinzendorf (1838)', 'I promised the Saviour… to become his pure follower, and entirely to renounce the world. And this resolution, with respect to honour and distinction, has since that time continued unchanged; and the reproach of Christ has always occasioned me joy.', 'discipleship,humility,joy,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 90 AND text = 'I promised the Saviour… to become his pure follower, and entirely to renounce the world. And this resolution, with respect to honour and distinction, has since that time continued unchanged; and the reproach of Christ has always occasioned me joy.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 90, 'Cited in August Gottlieb Spangenberg, The Life of Nicholas Lewis, Count Zinzendorf (1838)', 'My spirit returns to me again upon this journey… for the eyes of the Saviour guide me. I labour without any will or purpose of my own, and thus every thing succeeds.', 'guidance,surrender,work,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 90 AND text = 'My spirit returns to me again upon this journey… for the eyes of the Saviour guide me. I labour without any will or purpose of my own, and thus every thing succeeds.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 78, 'The Will to Believe and Other Essays, Is Life Worth Living? (1897)', 'Be not afraid of life. Believe that life is worth living, and your belief will help create the fact.', 'courage,faith,hope,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 78 AND text = 'Be not afraid of life. Believe that life is worth living, and your belief will help create the fact.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 78, 'The Will to Believe and Other Essays, Is Life Worth Living? (1897)', 'Not a victory is gained, not a deed of faithfulness or courage is done, except upon a maybe… It is only by risking our persons from one hour to another that we live at all.', 'courage,faith,perseverance,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 78 AND text = 'Not a victory is gained, not a deed of faithfulness or courage is done, except upon a maybe… It is only by risking our persons from one hour to another that we live at all.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 78, 'The Varieties of Religious Experience, Lecture II (1902)', 'There is a state of mind, known to religious men, but to no others, in which the will to assert ourselves and hold our own has been displaced by a willingness to close our mouths and be as nothing in the floods and waterspouts of God. In this state of mind, what we most dreaded has become the habitation of our safety, and the hour of our moral death has turned into our spiritual birthday.', 'surrender,faith,peace,transformation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 78 AND text = 'There is a state of mind, known to religious men, but to no others, in which the will to assert ourselves and hold our own has been displaced by a willingness to close our mouths and be as nothing in the floods and waterspouts of God. In this state of mind, what we most dreaded has become the habitation of our safety, and the hour of our moral death has turned into our spiritual birthday.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 78, 'The Varieties of Religious Experience, Lectures XIV and XV (1902)', 'The world is not yet with them, so they often seem in the midst of the world''s affairs to be preposterous. Yet they are impregnators of the world, vivifiers and animaters of potentialities of goodness which but for them would lie forever dormant. It is not possible to be quite as mean as we naturally are, when they have passed before us.', 'compassion,holiness,hope,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 78 AND text = 'The world is not yet with them, so they often seem in the midst of the world''s affairs to be preposterous. Yet they are impregnators of the world, vivifiers and animaters of potentialities of goodness which but for them would lie forever dormant. It is not possible to be quite as mean as we naturally are, when they have passed before us.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 78, 'Talks to Teachers on Psychology, The Gospel of Relaxation (1899)', 'The turbulent billows of the fretful surface leave the deep parts of the ocean undisturbed, and to him who has a hold on vaster and more permanent realities the hourly vicissitudes of his personal destiny seem relatively insignificant things. The really religious person is accordingly unshakable and full of equanimity, and calmly ready for any duty that the day may bring forth.', 'peace,faith,anxiety,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 78 AND text = 'The turbulent billows of the fretful surface leave the deep parts of the ocean undisturbed, and to him who has a hold on vaster and more permanent realities the hourly vicissitudes of his personal destiny seem relatively insignificant things. The really religious person is accordingly unshakable and full of equanimity, and calmly ready for any duty that the day may bring forth.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 78, 'Talks to Teachers on Psychology, On a Certain Blindness in Human Beings (1899)', 'Hands off: neither the whole of truth nor the whole of good is revealed to any single observer, although each observer gains a partial superiority of insight from the peculiar position in which he stands. Even prisons and sick-rooms have their special revelations.', 'humility,truth,compassion,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 78 AND text = 'Hands off: neither the whole of truth nor the whole of good is revealed to any single observer, although each observer gains a partial superiority of insight from the peculiar position in which he stands. Even prisons and sick-rooms have their special revelations.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Retrospect, ch. 3 ''Preparation for Service'' (1894)', 'If we are faithful to God in little things, we shall gain experience and strength that will be helpful to us in the more serious trials of life.', 'faithfulness,perseverance,suffering,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = 'If we are faithful to God in little things, we shall gain experience and strength that will be helpful to us in the more serious trials of life.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Retrospect, ch. 16 ''Timely Supplies'' (1894)', 'Not infrequently our God brings His people into difficulties on purpose that they may come to know Him as they could not otherwise do. Then He reveals Himself as "a very present help in trouble," and makes the heart glad indeed at each fresh revelation of a Father''s faithfulness.', 'suffering,providence,faithfulness,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = 'Not infrequently our God brings His people into difficulties on purpose that they may come to know Him as they could not otherwise do. Then He reveals Himself as "a very present help in trouble," and makes the heart glad indeed at each fresh revelation of a Father''s faithfulness.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Retrospect, ch. 9 ''Early Missionary Experiences'' (1894)', 'The cold, and even the hunger, the watchings and sleeplessness of nights of danger, and the feeling at times of utter isolation and helplessness, were well and wisely chosen, and tenderly and lovingly meted out. What circumstances could have rendered the Word of God more sweet, the presence of God more real, the help of God more precious?', 'suffering,providence,presence,scripture', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = 'The cold, and even the hunger, the watchings and sleeplessness of nights of danger, and the feeling at times of utter isolation and helplessness, were well and wisely chosen, and tenderly and lovingly meted out. What circumstances could have rendered the Word of God more sweet, the presence of God more real, the help of God more precious?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Retrospect, ch. 15 ''Settlement in Ningpo'' (1894)', 'My faith was not untried; it often, often failed, and I was so sorry and ashamed of the failure to trust such a Father. But oh! I was learning to know Him. I would not even then have missed the trial. He became so near, so real, so intimate.', 'faith,trust,suffering,presence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = 'My faith was not untried; it often, often failed, and I was so sorry and ashamed of the failure to trust such a Father. But oh! I was learning to know Him. I would not even then have missed the trial. He became so near, so real, so intimate.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Retrospect, ch. 1 ''The Power of Prayer'' (1894)', '…the promises were very real, and that prayer was in sober matter of fact transacting business with God, whether on one''s own behalf or on behalf of those for whom one sought His blessing.', 'prayer,faith,intercession,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = '…the promises were very real, and that prayer was in sober matter of fact transacting business with God, whether on one''s own behalf or on behalf of those for whom one sought His blessing.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Retrospect, ch. 3 ''Preparation for Service'' (1894)', '…my experience was that the less I spent on myself and the more I gave away, the fuller of happiness and blessing did my soul become. Unspeakable joy all the day long, and every day, was my happy experience.', 'generosity,joy,simplicity,sacrifice', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = '…my experience was that the less I spent on myself and the more I gave away, the fuller of happiness and blessing did my soul become. Unspeakable joy all the day long, and every day, was my happy experience.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Union and Communion, Section II ''Communion Broken: Restoration'' (1894)', 'Wonderful thought! that God should desire fellowship with us; and that He whose love once made Him the Man of Sorrows may now be made the Man of Joys by the loving devotion of human hearts.', 'love,joy,devotion,intimacy', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = 'Wonderful thought! that God should desire fellowship with us; and that He whose love once made Him the Man of Sorrows may now be made the Man of Joys by the loving devotion of human hearts.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Union and Communion, Section I ''The Unsatisfied Life and Its Remedy'' (1894)', 'Are we not all too apt to seek Him rather because of our need than for His joy and pleasure? This should not be.', 'devotion,prayer,love,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = 'Are we not all too apt to seek Him rather because of our need than for His joy and pleasure? This should not be.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Union and Communion, Section VI ''Unrestrained Communion'' (1894)', 'All His resources of wisdom and might are hers; though journeying she is at rest, though in the wilderness she is satisfied, while leaning upon her Beloved.', 'rest,trust,peace,dependence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = 'All His resources of wisdom and might are hers; though journeying she is at rest, though in the wilderness she is satisfied, while leaning upon her Beloved.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Cited in Howard Taylor and Geraldine Taylor, Hudson Taylor and the China Inland Mission (1918)', 'I sometimes think that God must have been looking for some one small enough and weak enough for Him to use, so that all the glory might be His, and that He found me.', 'humility,grace,calling,sovereignty', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = 'I sometimes think that God must have been looking for some one small enough and weak enough for Him to use, so that all the glory might be His, and that He found me.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Cited in Howard Taylor and Geraldine Taylor, Hudson Taylor and the China Inland Mission (1918)', 'Depend upon it, God''s work, done in God''s way, will never lack God''s supplies.', 'faith,provision,trust,obedience', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = 'Depend upon it, God''s work, done in God''s way, will never lack God''s supplies.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Cited in Howard Taylor and Geraldine Taylor, Hudson Taylor and the China Inland Mission (1918)', 'We need a faith that rests on a great God, and expects Him to keep His own word and to do just as He has promised.', 'faith,trust,prayer,faithfulness', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = 'We need a faith that rests on a great God, and expects Him to keep His own word and to do just as He has promised.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Cited in Howard Taylor and Geraldine Taylor, Hudson Taylor and the China Inland Mission (1918)', 'Faith, He tries, but sustains: and when our faithfulness fails, His remains unshaken.', 'faith,faithfulness,trust,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = 'Faith, He tries, but sustains: and when our faithfulness fails, His remains unshaken.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 82, 'Cited in Howard Taylor and Geraldine Taylor, Hudson Taylor and the China Inland Mission (1918)', 'How few of the Lord''s people have practically recognised the truth that Christ is either Lord of all, or is not Lord at all!', 'discipleship,surrender,obedience,authority', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 82 AND text = 'How few of the Lord''s people have practically recognised the truth that Christ is either Lord of all, or is not Lord at all!');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 86, 'In Darkest England and the Way Out, Preface (1890)', 'When but a mere child the degradation and helpless misery of the poor Stockingers of my native town…kindled in my heart yearnings to help the poor which have continued to this day and which have had a powerful influence on my whole life.', 'compassion,justice,calling,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 86 AND text = 'When but a mere child the degradation and helpless misery of the poor Stockingers of my native town…kindled in my heart yearnings to help the poor which have continued to this day and which have had a powerful influence on my whole life.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 86, 'Cited in Harold Begbie, The Life of General William Booth, Vol. II (1920)', 'Go straight for souls, and go for the worst.', 'evangelism,service,love,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 86 AND text = 'Go straight for souls, and go for the worst.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 86, 'In Darkest England and the Way Out, Part 1, ch. 4 ''The Out-of-Works'' (1890)', 'There is no gainsaying the immensity of the problem. It is appalling enough to make us despair. But those who do not put their trust in man alone, but in One who is Almighty, have no right to despair. To despair is to lose faith; to despair is to forget God…', 'hope,faith,trust,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 86 AND text = 'There is no gainsaying the immensity of the problem. It is appalling enough to make us despair. But those who do not put their trust in man alone, but in One who is Almighty, have no right to despair. To despair is to lose faith; to despair is to forget God…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 86, 'In Darkest England and the Way Out, Part 1, ch. 4 ''The Out-of-Works'' (1890)', 'To attempt to save the Lost, we must accept no Limitations to human brotherhood. …we who call ourselves by the name of Christ are not worthy to profess to be His disciples until we have set an open door before the least and worst of these who are now apparently imprisoned for life in a horrible dungeon of misery and despair.', 'compassion,discipleship,justice,community', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 86 AND text = 'To attempt to save the Lost, we must accept no Limitations to human brotherhood. …we who call ourselves by the name of Christ are not worthy to profess to be His disciples until we have set an open door before the least and worst of these who are now apparently imprisoned for life in a horrible dungeon of misery and despair.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 86, 'In Darkest England and the Way Out, Part 1, ch. 5 ''On the Verge of the Abyss'' (1890)', 'To get a man soundly saved it is not enough to put on him a pair of new breeches, to give him regular work, or even to give him a University education. These things are all outside a man, and if the inside remains unchanged you have wasted your labour.', 'transformation,salvation,regeneration,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 86 AND text = 'To get a man soundly saved it is not enough to put on him a pair of new breeches, to give him regular work, or even to give him a University education. These things are all outside a man, and if the inside remains unchanged you have wasted your labour.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 86, 'In Darkest England and the Way Out, Part 1, ch. 1 ''Why "Darkest England"?'' (1890)', 'Why all this apparatus of temples and meeting-houses to save men from perdition in a world which is to come, while never a helping hand is stretched out to save them from the inferno of their present life?', 'justice,compassion,church,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 86 AND text = 'Why all this apparatus of temples and meeting-houses to save men from perdition in a world which is to come, while never a helping hand is stretched out to save them from the inferno of their present life?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 86, 'In Darkest England and the Way Out, Part 1, ch. 2 ''The Submerged Tenth'' (1890)', 'These are the two points of the Cab Horse''s Charter. When he is down he is helped up, and while he lives he has food, shelter and work.', 'justice,dignity,compassion,work', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 86 AND text = 'These are the two points of the Cab Horse''s Charter. When he is down he is helped up, and while he lives he has food, shelter and work.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 86, 'In Darkest England and the Way Out, Part 2, ch. 7 ''Can It Be Done, and How?'' (1890)', 'We keep our powder dry, but we trust in Jehovah. We go not forth in our own strength to this battle, our dependence is upon Him who can influence the heart of man.', 'trust,dependence,courage,sovereignty', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 86 AND text = 'We keep our powder dry, but we trust in Jehovah. We go not forth in our own strength to this battle, our dependence is upon Him who can influence the heart of man.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 86, 'In Darkest England and the Way Out, Part 2, ch. 2 ''To the Rescue! The City Colony'' (1890)', 'We talk freely about Salvation, because it is to us the very light and joy of our existence. We are happy, and we wish others to share our joy.', 'joy,salvation,witness,community', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 86 AND text = 'We talk freely about Salvation, because it is to us the very light and joy of our existence. We are happy, and we wish others to share our joy.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 86, 'Cited in Harold Begbie, The Life of General William Booth, Vol. I (1920)', 'Ask the Salvationist, and the answer will be both from theory and experience, that the vilest and worst can be saved to the uttermost, for all things are possible to him that believeth.', 'hope,salvation,faith,transformation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 86 AND text = 'Ask the Salvationist, and the answer will be both from theory and experience, that the vilest and worst can be saved to the uttermost, for all things are possible to him that believeth.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 86, 'Cited in Harold Begbie, The Life of General William Booth, Vol. II (1920)', 'I have done what I could for God and for the people with my eyes. Now I shall do what I can for God and for the people without my eyes.', 'perseverance,suffering,service,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 86 AND text = 'I have done what I could for God and for the people with my eyes. Now I shall do what I can for God and for the people without my eyes.');
