INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 97, 'The Unoccupied Mission Fields of Africa and Asia, Chapter VIII (1911)', 'The challenge of the unoccupied fields of the world is one to great faith and, therefore, to great sacrifice. Our willingness to sacrifice for an enterprise is always in proportion to our faith in that enterprise.', 'faith,sacrifice,courage,mission', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 97 AND text = 'The challenge of the unoccupied fields of the world is one to great faith and, therefore, to great sacrifice. Our willingness to sacrifice for an enterprise is always in proportion to our faith in that enterprise.');
