INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 6, 'Cited in Gotthard Lechler, John Wycliffe and His English Precursors (1884)', 'Holy Scripture is the faultless, most true, most perfect, and most holy law of God, which it is the duty of all men to learn to know, to defend, and to observe, inasmuch as they are bound to serve the Lord in accordance with it, under the promise of an eternal reward.', 'scripture,truth,obedience,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 6 AND text = 'Holy Scripture is the faultless, most true, most perfect, and most holy law of God, which it is the duty of all men to learn to know, to defend, and to observe, inasmuch as they are bound to serve the Lord in accordance with it, under the promise of an eternal reward.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 6, 'Cited in Gotthard Lechler, John Wycliffe and His English Precursors (1884)', 'The nearer the life of a Christian comes to Christ, the more rich it is in virtue. It follows that men''s departure from the principles of the Christian religion is owing to their having too high a value for many teachers who stand in opposition to Christ, to the neglect of the doctrine and example of the best Master and Leader.', 'discipleship,truth,holiness,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 6 AND text = 'The nearer the life of a Christian comes to Christ, the more rich it is in virtue. It follows that men''s departure from the principles of the Christian religion is owing to their having too high a value for many teachers who stand in opposition to Christ, to the neglect of the doctrine and example of the best Master and Leader.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 6, 'Cited in Gotthard Lechler, John Wycliffe and His English Precursors (1884)', 'I confess that in my own case I have often, from a motive of vain ambition, departed from the doctrine of Scripture both in my reasonings and my replies, while my aim was to attain the show of fame among the people, and at the same time to strip off the pretensions of ambitious sophists.', 'humility,repentance,truth,scripture', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 6 AND text = 'I confess that in my own case I have often, from a motive of vain ambition, departed from the doctrine of Scripture both in my reasonings and my replies, while my aim was to attain the show of fame among the people, and at the same time to strip off the pretensions of ambitious sophists.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 6, 'Cited in Gotthard Lechler, John Wycliffe and His English Precursors (1884)', 'Let God be my witness, that before everything I strive for God''s glory and the good of the Church, from reverence of Holy Scripture, and adherence to the law of Christ.', 'integrity,courage,truth,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 6 AND text = 'Let God be my witness, that before everything I strive for God''s glory and the good of the Church, from reverence of Holy Scripture, and adherence to the law of Christ.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 6, 'Cited in Gotthard Lechler, John Wycliffe and His English Precursors (1884)', 'If we had Christ alone before our eyes, and if we served Him continually in teaching and learning, in prayer, work, and rest, then should we all be brothers, sisters, and mothers of our Lord Jesus Christ', 'discipleship,prayer,service,community', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 6 AND text = 'If we had Christ alone before our eyes, and if we served Him continually in teaching and learning, in prayer, work, and rest, then should we all be brothers, sisters, and mothers of our Lord Jesus Christ');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 6, 'Cited in Gotthard Lechler, John Wycliffe and His English Precursors (1884)', 'The priests learn and teach Holy Scripture for this purpose, that the Church may learn to know the walk of Christ, and may be led to love Christ Himself.', 'scripture,discipleship,love,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 6 AND text = 'The priests learn and teach Holy Scripture for this purpose, that the Church may learn to know the walk of Christ, and may be led to love Christ Himself.');
