INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 17, 'De Regno Christi, Book 2, Chapter 17 (1550)', 'I Confesse that wee beeing free in Christ are not bound to the civil Laws of Moses in every circumstance, yet seeing no laws can be more honest, just, and wholsom, then those which God himself gave, who is eternal wisdom & goodnes, I see not why Christians, in things which no lesse appertain to them, ought not to follow the laws of God, rather then of any men.', 'justice,wisdom,scripture,freedom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 17 AND text = 'I Confesse that wee beeing free in Christ are not bound to the civil Laws of Moses in every circumstance, yet seeing no laws can be more honest, just, and wholsom, then those which God himself gave, who is eternal wisdom & goodnes, I see not why Christians, in things which no lesse appertain to them, ought not to follow the laws of God, rather then of any men.');
