INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 94, 'By My Spirit (1929)', 'It is vain for us to pray while conscious that we have injured another. Let us first make amends to the injured one before we dare approach God at either the private or the public altar.', 'reconciliation,prayer,justice,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 94 AND text = 'It is vain for us to pray while conscious that we have injured another. Let us first make amends to the injured one before we dare approach God at either the private or the public altar.');
