INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 94, 'When the Spirit''s Fire Swept Korea (1943)', 'It is always so as soon as God gets first place; but, as a rule, the Church, which professes to be Christ’s, will not cease her busy round of activities and give God a chance by waiting upon Him in prayer.', 'prayer,patience,devotion,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 94 AND text = 'It is always so as soon as God gets first place; but, as a rule, the Church, which professes to be Christ’s, will not cease her busy round of activities and give God a chance by waiting upon Him in prayer.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Where Is God in a Coronavirus World?, Chapter 5 (2020)', 'At the heart of the Christian message is the death of Jesus Christ on a cross just outside Jerusalem. The question at once arises: if he is God incarnate, what was he doing on a cross? Well, it at the very least means that God has not remained distant from human pain and suffering but has himself experienced it.', 'suffering,hope,faith,compassion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'At the heart of the Christian message is the death of Jesus Christ on a cross just outside Jerusalem. The question at once arises: if he is God incarnate, what was he doing on a cross? Well, it at the very least means that God has not remained distant from human pain and suffering but has himself experienced it.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Where Is God in a Coronavirus World?, Chapter 6 (2020)', '…we should be looking for how we might love others, even at cost to ourselves—for that is how God has loved every Christian in the person of his Son, by dying for them on the cross.', 'love,service,compassion,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = '…we should be looking for how we might love others, even at cost to ourselves—for that is how God has loved every Christian in the person of his Son, by dying for them on the cross.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Where Is God in a Coronavirus World?, Chapter 5 (2020)', 'But hope is found in another corona: the crown of thorns that was forced on Jesus'' head at his trial before his execution. That corona shows us just how deep the break between creature and Creator goes.', 'hope,suffering,grace,redemption', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'But hope is found in another corona: the crown of thorns that was forced on Jesus'' head at his trial before his execution. That corona shows us just how deep the break between creature and Creator goes.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Where Is God in a Coronavirus World?, Chapter 2 (2020)', 'We all wish to have intellectual clarity, and many people will spend hours watching news programmes and trawling the internet in the hope of gleaning some new piece of information that may help them understand what is happening. However, intellectual analysis does not easily penetrate a veil of tears.', 'suffering,compassion,truth,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'We all wish to have intellectual clarity, and many people will spend hours watching news programmes and trawling the internet in the hope of gleaning some new piece of information that may help them understand what is happening. However, intellectual analysis does not easily penetrate a veil of tears.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'God''s Undertaker: Has Science Buried God?, Chapter 4 (2007)', 'The more we get to know about our universe, the more the hypothesis that there is a Creator God, who designed the universe for a purpose, gains in credibility as the best explanation of why we are here.', 'creation,faith,truth,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'The more we get to know about our universe, the more the hypothesis that there is a Creator God, who designed the universe for a purpose, gains in credibility as the best explanation of why we are here.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'God''s Undertaker: Has Science Buried God?, Epilogue (2007)', 'But if there is a Mind behind the universe, and if that Mind intends us to be here, the really big question is: Why are we here? What is the purpose of our existence? It is this question above all that exercises the human heart.', 'purpose,creation,truth,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'But if there is a Mind behind the universe, and if that Mind intends us to be here, the really big question is: Why are we here? What is the purpose of our existence? It is this question above all that exercises the human heart.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'God''s Undertaker: Has Science Buried God?, Epilogue (2007)', 'It is no abstraction, or even impersonal force, that lies behind the universe. God, the Creator, is a person.', 'creation,faith,truth,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'It is no abstraction, or even impersonal force, that lies behind the universe. God, the Creator, is a person.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Gunning for God, Chapter 5 (2011)', 'For me, this is the beginning of hope; and it is a living hope that cannot be smashed by the enemy of death. The story does not end in the darkness of the cross.', 'hope,suffering,resurrection,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'For me, this is the beginning of hope; and it is a living hope that cannot be smashed by the enemy of death. The story does not end in the darkness of the cross.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Gunning for God, Chapter 5 (2011)', 'On the other hand, atheism has got rid of hope; yet I as a Christian have hope, even in the face of suffering and evil. … Human conscience and desire for justice are not a delusion.', 'hope,justice,suffering,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'On the other hand, atheism has got rid of hope; yet I as a Christian have hope, even in the face of suffering and evil. … Human conscience and desire for justice are not a delusion.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Gunning for God, Chapter 5 (2011)', 'However, I believe that death is not the end, and that God is a God of compensation. The resurrection of Jesus Christ demonstrates that there is to be a final assessment at which God will not only be just, but will also be seen to be just.', 'resurrection,justice,hope,sovereignty', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'However, I believe that death is not the end, and that God is a God of compensation. The resurrection of Jesus Christ demonstrates that there is to be a final assessment at which God will not only be just, but will also be seen to be just.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Can Science Explain Everything?, Chapter 2 (2019)', 'The God of the Bible is not a god of the gaps. He is the God of the whole show. He is the God of the bits of the universe we don''t understand and the bits we do.', 'creation,sovereignty,faith,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'The God of the Bible is not a god of the gaps. He is the God of the whole show. He is the God of the bits of the universe we don''t understand and the bits we do.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Can Science Explain Everything?, Chapter 9 (2019)', 'It says that, if they will, anyone can be forgiven and find a new life and friendship with God—whoever they are; whatever they have done.', 'grace,forgiveness,hope,redemption', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'It says that, if they will, anyone can be forgiven and find a new life and friendship with God—whoever they are; whatever they have done.');
