INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Seven Days That Divide the World, Chapter 5 (2011)', 'God is not some distant deistic figure uninterested in his work. He regards his creation with the enthusiasm and joy of a skilful artist who is delighted at what he has done…', 'creation,joy,providence,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'God is not some distant deistic figure uninterested in his work. He regards his creation with the enthusiasm and joy of a skilful artist who is delighted at what he has done…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Jesus and the Disinherited, Chapter 1, Jesus—An Interpretation (1949)', 'The basic fact is that Christianity as it was born in the mind of this Jewish teacher and thinker appears as a technique of survival for the oppressed.', 'justice,hope,faith,compassion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'The basic fact is that Christianity as it was born in the mind of this Jewish teacher and thinker appears as a technique of survival for the oppressed.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Jesus and the Disinherited, Chapter 2, Fear (1949)', 'The awareness of being a child of God tends to stabilize the ego and results in a new courage, fearlessness, and power.', 'courage,faith,identity,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'The awareness of being a child of God tends to stabilize the ego and results in a new courage, fearlessness, and power.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Jesus and the Disinherited, Chapter 2, Fear (1949)', 'Such a man recognizes that death cannot possibly be the worst thing in the world. There are some things that are worse than death. To deny one’s own integrity of personality in the presence of the human challenge is one of those things.', 'courage,integrity,truth,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'Such a man recognizes that death cannot possibly be the worst thing in the world. There are some things that are worse than death. To deny one’s own integrity of personality in the presence of the human challenge is one of those things.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Jesus and the Disinherited, Chapter 3, Deception (1949)', 'The penalty of deception is to become a deception, with all sense of moral discrimination vitiated. A man who lies habitually becomes a lie, and it is increasingly impossible for him to know when he is lying and when he is not.', 'truth,integrity,humility,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'The penalty of deception is to become a deception, with all sense of moral discrimination vitiated. A man who lies habitually becomes a lie, and it is increasingly impossible for him to know when he is lying and when he is not.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Jesus and the Disinherited, Chapter 4, Hate (1949)', 'Jesus rejected hatred. It was not because he lacked the vitality or the strength. It was not because he lacked the incentive. … He affirmed life; and hatred was the great denial.', 'love,peace,courage,justice', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'Jesus rejected hatred. It was not because he lacked the vitality or the strength. It was not because he lacked the incentive. … He affirmed life; and hatred was the great denial.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Jesus and the Disinherited, Epilogue (1949)', 'Thus interpreted, he belongs to no age, no race, no creed. When men look into his face, they see etched the glory of their own possibilities, and their hearts whisper, “Thank you and thank God!”', 'hope,faith,gratitude,christ', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'Thus interpreted, he belongs to no age, no race, no creed. When men look into his face, they see etched the glory of their own possibilities, and their hearts whisper, “Thank you and thank God!”');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Meditations of the Heart, Keep Alive the Dream in the Heart (1953)', 'Keep alive the dream; for as long as a man has a dream in his heart, he cannot lose the significance of living.', 'hope,perseverance,purpose,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'Keep alive the dream; for as long as a man has a dream in his heart, he cannot lose the significance of living.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Meditations of the Heart, Lord, Lord, Open Unto Me (1953)', 'Open unto me—light for my darkness. Open unto me—courage for my fear. Open unto me—hope for my despair. Open unto me—peace for my turmoil.', 'prayer,hope,courage,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'Open unto me—light for my darkness. Open unto me—courage for my fear. Open unto me—hope for my despair. Open unto me—peace for my turmoil.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Meditations of the Heart, How Good to Center Down! (1953)', 'How good it is to center down! To sit quietly and see one’s self pass by! The streets of our minds seethe with endless traffic; Our spirits resound with clashings, with noisy silences, While something deep within hungers and thirsts for the still moment and the resting lull.', 'prayer,peace,rest,contemplation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'How good it is to center down! To sit quietly and see one’s self pass by! The streets of our minds seethe with endless traffic; Our spirits resound with clashings, with noisy silences, While something deep within hungers and thirsts for the still moment and the resting lull.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Meditations of the Heart, The Growing Edge (1953)', 'Look well to the growing edge. All around us worlds are dying and new worlds are being born; all around us life is dying and life is being born. The fruit ripens on the tree, the roots are silently at work in the darkness of the earth against a time when there shall be new leaves, fresh blossoms, green fruit.', 'hope,creation,perseverance,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'Look well to the growing edge. All around us worlds are dying and new worlds are being born; all around us life is dying and life is being born. The fruit ripens on the tree, the roots are silently at work in the darkness of the earth against a time when there shall be new leaves, fresh blossoms, green fruit.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'The Inward Journey, A Strange Freedom (1961)', 'It is a strange freedom to be adrift in the world of men without a sense of anchor anywhere. Always there is the need of mooring, the need for the firm grip on something that is rooted and will not give.', 'freedom,faith,longing,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'It is a strange freedom to be adrift in the world of men without a sense of anchor anywhere. Always there is the need of mooring, the need for the firm grip on something that is rooted and will not give.');
